const fs = require('fs');
const path = require('path');

const workspace = __dirname;
const manifestPath = path.join(workspace, 'backup-manifest.json');

const files = fs.readdirSync(workspace, { withFileTypes: true })
  .filter(entry => entry.isFile())
  .filter(entry => !entry.name.startsWith('.'))
  .filter(entry => entry.name !== 'backup-manifest.json')
  .map(entry => entry.name)
  .sort();

fs.writeFileSync(manifestPath, JSON.stringify({ files }, null, 2) + '\n');

console.log(JSON.stringify({ files }));

